create table `ticket_message_attachments` (`id` bigint unsigned not null auto_increment primary key, `uuid` uuid not null, `filename` varchar(255) not null, `path` varchar(255) not null, `filesize` bigint unsigned not null, `mime_type` varchar(255) not null, `ticket_message_id` bigint unsigned not null, `created_at` timestamp null, `updated_at` timestamp null) default character set {{charset}} collate {{collation}};
alter table `ticket_message_attachments` add constraint `ticket_message_attachments_ticket_message_id_foreign` foreign key (`ticket_message_id`) references `ticket_messages` (`id`) on delete cascade;
